import * as T from './vendor/three.module.min.js';
import {PokerTavern} from './poker-tavern.mjs';
export class Guandan3D extends PokerTavern{
 showTurn(seat,done=false){
  if(!this.turnPointer){const root=new T.Group();root.position.set(0,1.40,0);this.scene.add(root);this.turnPointer=root;
   const ring=new T.Mesh(new T.RingGeometry(.25,.29,32),new T.MeshBasicMaterial({color:0xc8ad68,side:T.DoubleSide}));ring.rotation.x=-Math.PI/2;root.add(ring);
   const shape=new T.Shape();shape.moveTo(-.075,-.12);shape.lineTo(.075,-.12);shape.lineTo(.075,.14);shape.lineTo(.17,.14);shape.lineTo(0,.40);shape.lineTo(-.17,.14);shape.lineTo(-.075,.14);shape.closePath();
   const arrow=new T.Mesh(new T.ShapeGeometry(shape),new T.MeshBasicMaterial({color:0xe1ed9e,side:T.DoubleSide}));arrow.rotation.x=Math.PI/2;arrow.position.y=.012;root.add(arrow);
  }
  this.turnPointer.position.z=this.container?.clientHeight<=500?-1.5:0;this.turnPointer.visible=!done&&seat>=0;const point=this.seatPoint(seat);this.turnAngle=Math.atan2(point.x,point.z-this.turnPointer.position.z);if(this.reduced)this.turnPointer.rotation.y=this.turnAngle;
 }
 frame(){if(this.turnPointer){const now=performance.now(),dt=Math.min(.05,(now-(this.pointerTime??now))/1000);this.pointerTime=now;const d=Math.atan2(Math.sin(this.turnAngle-this.turnPointer.rotation.y),Math.cos(this.turnAngle-this.turnPointer.rotation.y));this.turnPointer.rotation.y+=d*(1-Math.exp(-12*dt))}super.frame()}
 buildTable(){this.isGuandanTable=true;super.buildTable()}
 showPlays(plays,trick=0){this.gdSeats??=new Map();for(let i=0;i<4;i++){const move=plays[i],old=this.gdSeats.get(i);const signature=move?JSON.stringify([trick,move.key,move.cards.map(c=>[c.id,c.r,c.s])]):null;if(old?.signature===signature)continue;if(old){this.tweens=this.tweens.filter(t=>!old.group.children.includes(t.obj));this.disposeGroup(old.group);this.gdSeats.delete(i)}if(!move)continue;const group=new T.Group(),pos=[new T.Vector3(0,1.343,.9),new T.Vector3(-2.65,1.343,-.55),new T.Vector3(0,1.343,-2.6),new T.Vector3(2.65,1.343,-.55)][i],width=Math.min(.43,1.9/move.size);this.scene.add(group);this.gdSeats.set(i,{signature,group});move.cards.forEach((c,n)=>{const obj=this.makeCard(c,width,width*1.42);obj.rotation.x=-Math.PI/2;obj.position.copy(this.seatPoint(i));group.add(obj);this.tween(obj,new T.Vector3(pos.x+(n-(move.size-1)/2)*(width+.018),pos.y,pos.z),.48,n*.018,.12)});if(['bomb','kings','flush','straight','full','pairs','plate'].includes(move.type)){const color=move.type==='bomb'?0xff9a45:move.type==='flush'?0xffda65:move.type==='full'?0xcb9df4:0x8fe3d5,fx=new T.Group();fx.position.copy(pos);fx.position.y+=.025;fx.rotation.x=-Math.PI/2;const ring=new T.Mesh(new T.RingGeometry(.55,.58,64),new T.MeshBasicMaterial({color,transparent:true,opacity:.8,depthWrite:false}));fx.add(ring);this.scene.add(fx);this.effects.push({group:fx,start:this.elapsed,duration:this.reduced?.5:1.3,role:4})}}}
 faceTexture(c){if(!c||c.r<=14)return super.faceTexture(c);const key='gd-joker-'+c.r;if(this.textures.has(key))return this.textures.get(key);const v=document.createElement('canvas');v.width=512;v.height=768;const x=v.getContext('2d');x.fillStyle='#faf7e8';x.fillRect(0,0,512,768);x.strokeStyle='#c4c7bb';x.lineWidth=4;x.strokeRect(16,16,480,736);x.fillStyle=c.r===16?'#af3037':'#1d3027';x.font='bold 76px serif';x.textAlign='center';x.fillText(c.r===16?'大王':'小王',256,132);x.font='230px serif';x.fillText('★',256,490);x.font='42px Georgia';x.fillText('JOKER',256,650);const tex=new T.CanvasTexture(v);tex.colorSpace=T.SRGBColorSpace;this.textures.set(key,tex);return tex}
 showMove(move,seat){if(this.gdTarget===move)return;this.gdTarget=move;if(this.gdCards){const old=this.gdCards;this.tweens=this.tweens.filter(t=>!old.children.includes(t.obj));this.poseTweens=this.poseTweens.filter(t=>!old.children.includes(t.obj));this.disposeGroup(old)}this.gdCards=null;if(!move)return;const group=new T.Group();this.gdCards=group;this.scene.add(group);const width=Math.min(.53,3.7/move.cards.length),start=this.seatPoint(seat);move.cards.forEach((c,i)=>{const obj=this.makeCard(c,width,width*1.42);obj.rotation.x=-Math.PI/2;obj.position.copy(start);obj.position.y=1.4+i*.008;group.add(obj);if(move.tier){obj.userData.face.material.emissive.setHex(0xa27a19);obj.userData.face.material.emissiveIntensity=.16}this.tween(obj,new T.Vector3((i-(move.cards.length-1)/2)*(width+.035),1.343,-1.7),.5,i*.015,.17)});const rig=this.rigs.find(r=>r.seat===seat);if(rig)rig.gesture=1.2}
}
